use std::fs

fn parse_line(line: string) -> Vec<string> {
    let cs: Vec<char> = line.chars().collect()
    let mut fields: Vec<string> = []
    let mut cur: string = ""
    let mut inq: bool = false
    let mut pend: bool = false
    for c in cs {
        if pend && c == '"' {
            cur.push('"')
            pend = false
        } else {
            if pend {
                inq = false
                pend = false
            }
            if inq {
                if c == '"' {
                    pend = true
                } else {
                    cur.push(c)
                }
            } else if c == '"' {
                inq = true
            } else if c == ',' {
                fields.push(cur)
                cur = ""
            } else {
                cur.push(c)
            }
        }
    }
    fields.push(cur)
    fields
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for raw in text.lines() {
        let line = raw.trim_end_matches('\r')
        let fields = parse_line(line)
        let mut parts: Vec<string> = []
        for f in fields {
            parts.push("[${f}]")
        }
        println("${parts.len()}: ${parts.join("|")}")
    }
}

